// Independent CFB v4 layout, deliberately not generated by the parser under test.
export function v4File() {
  const bytes = Buffer.alloc(4 * 4096);
  Buffer.from("d0cf11e0a1b11ae1", "hex").copy(bytes);
  for (const [offset, value] of [
    [24, 62],
    [26, 4],
    [28, 65534],
    [30, 12],
    [32, 6],
  ])
    bytes.writeUInt16LE(value, offset);
  for (const [offset, value] of [
    [40, 1],
    [44, 1],
    [48, 1],
    [56, 4096],
    [60, 0xfffffffe],
    [68, 0xfffffffe],
  ])
    bytes.writeUInt32LE(value, offset);
  bytes.fill(255, 76, 512);
  bytes.writeUInt32LE(0, 76);
  bytes.fill(255, 4096, 8192);
  for (const [offset, value] of [
    [4096, 0xfffffffd],
    [4100, 0xfffffffe],
    [4104, 0xfffffffe],
  ])
    bytes.writeUInt32LE(value, offset);
  function entry(offset, name, kind, start, size, child = 0xffffffff) {
    const encoded = Buffer.from(name + "\0", "utf16le");
    encoded.copy(bytes, offset);
    bytes.writeUInt16LE(encoded.length, offset + 64);
    bytes[offset + 66] = kind;
    bytes[offset + 67] = 1;
    for (const [field, value] of [
      [68, 0xffffffff],
      [72, 0xffffffff],
      [76, child],
      [116, start],
      [120, size],
    ])
      bytes.writeUInt32LE(value, offset + field);
  }
  entry(8192, "Root Entry", 5, 0xfffffffe, 0, 1);
  entry(8320, "\ufffd", 2, 2, 4096);
  return bytes;
}

// A real WASM module that exports only the ABI version, for initialization failures.
export function versionModule(version) {
  const name = [...new TextEncoder().encode("hwpjs_abi_version")];
  return new Uint8Array([
    0,
    97,
    115,
    109,
    1,
    0,
    0,
    0,
    1,
    5,
    1,
    96,
    0,
    1,
    127,
    3,
    2,
    1,
    0,
    7,
    name.length + 4,
    1,
    name.length,
    ...name,
    0,
    0,
    10,
    6,
    1,
    4,
    0,
    65,
    version,
    11,
  ]);
}
